<div class="toolbar"><p class="muted">Control de materiales, lotes y consumos con trazabilidad.</p><a class="button" href="#stock-movement"><?= icon('plus',18) ?> Registrar movimiento</a></div>
<section class="panel"><div class="panel-heading"><h2>Materiales</h2><span class="muted">Las existencias se modifican mediante movimientos.</span></div><div class="table-wrap" tabindex="0" role="region" aria-label="Tabla de registros"><table><thead><tr><th>Código</th><th>Material</th><th>Categoría</th><th>Disponible</th><th>Mínimo</th><th>Estado</th></tr></thead><tbody><?php foreach($rows as $i): ?><tr><td><?= e($i['code']) ?></td><td><strong><?= e($i['name']) ?></strong><small><?= e($i['unit']) ?></small></td><td><?= e($i['category']) ?></td><td><?= e($i['stock']) ?></td><td><?= e($i['min_stock']) ?></td><td><?= (float)$i['stock']<=(float)$i['min_stock'] ? '<span class="badge pending">Stock bajo</span>':'<span class="badge completed">Disponible</span>' ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6" class="empty">Registra un material y luego su entrada inicial.</td></tr><?php endif; ?></tbody></table></div></section>
<div class="two-columns"><section class="panel form-panel" id="stock-movement"><h2>Entrada o salida</h2><form method="post" class="form-grid" data-loading><?= csrf_field() ?><?php choose('item_id','Material',array_column($rows,'name','id'),$_POST['item_id'] ?? ''); field('quantity','Cantidad (+ entrada / − salida)',$_POST['quantity'] ?? '','number',true,'step="0.01"'); field('lot','Lote',$_POST['lot'] ?? ''); field('expires_on','Vencimiento (nuevo lote)',$_POST['expires_on'] ?? '','date',false); field('reason','Motivo del movimiento',$_POST['reason'] ?? ''); ?><button class="button">Guardar movimiento</button></form></section><details class="panel form-panel"><summary>Registrar nuevo material</summary><form method="post" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="item"><?php field('code','Código'); field('name','Nombre'); field('category','Categoría'); field('unit','Unidad de medida'); field('min_stock','Stock mínimo','0','number',true,'min="0" step="0.01"'); ?><button class="button">Crear material</button></form></details></div>
<section class="panel"><div class="panel-heading"><h2>Lotes y vencimientos</h2></div><div class="table-wrap" tabindex="0" role="region" aria-label="Tabla de registros"><table><thead><tr><th>Material</th><th>Lote</th><th>Stock</th><th>Vencimiento</th><th>Estado</th></tr></thead><tbody><?php foreach($lots as $l): ?><tr><td><?= e($l['name']) ?></td><td><?= e($l['lot']) ?></td><td><?= e($l['stock']) ?></td><td><?= e($l['expires_on'] ?: 'No aplica') ?></td><td><?php if($l['expires_on'] && $l['expires_on']<date('Y-m-d')): ?><span class="badge cancelled">Vencido</span><?php else: ?><span class="badge completed">Vigente</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="panel"><div class="panel-heading"><h2>Últimos 100 movimientos</h2></div><div class="table-wrap" tabindex="0" role="region" aria-label="Tabla de registros"><table><thead><tr><th>Material / lote</th><th>Cantidad</th><th>Motivo</th><th>Responsable</th><th>Fecha</th></tr></thead><tbody><?php foreach($movements as $m): ?><tr><td><?= e($m['name']) ?><small><?= e($m['lot']) ?></small></td><td><strong><?= (float)$m['quantity']>0 ? '+':'' ?><?= e($m['quantity']) ?></strong></td><td><?= e($m['reason']) ?></td><td><?= e($m['author']) ?></td><td><?= local_date($m['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
